contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // We call mintSynth from an arbitrary caller address by having this contract be the msg.sender.
    // Parameters:
    // - pool: address of caller that will invoke c.mintSynth (this contract's address is used as msg.sender when calling from here)
    // - member: receiver address for minted synths
    // - amount: amount to mint
    // The rule asserts that after mintSynth returns, the recorded LP balance for the caller (mapSynth_LPBalance[pool]) is either zero
    // or at most the caller's current LP token balance (ensuring only legitimate curated pools cause positive recorded LP balance).
    // On the original contract P this holds because only curated pools can call mintSynth; on mutant M the relaxed modifier allows DEPLOYER
    // (which may not actually be a curated pool) to call mintSynth and thereby increase mapSynth_LPBalance, violating the invariant for some inputs.

    function run(address pool, address member, uint256 amount) external returns (uint256 recordedLP, uint256 actualLP) {
        // precondition: pool must be this contract so that msg.sender inside C is a controlled caller
        // but we keep it generic: we will call c.mintSynth where msg.sender is address(this)
        // perform the state-changing call
        c.mintSynth(member, amount);

        // observe the stored mapSynth_LPBalance for the pool equal to address(this)
        recordedLP = c.getmapAddress_LPBalance(address(this));

        // observe the actual LP token balance of this contract for the same pool token
        // That requires calling BEP20 balance via the pool address as token; pools are ERC20-like so we can query balanceOf
        // Using low-level staticcall to call balanceOf on the pool contract
        (bool ok, bytes memory data) = address(address(this)).staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        // If the pool address isn't an ERC20, treat actualLP as 0
        if (!ok || data.length < 32) {
            actualLP = 0;
        } else {
            actualLP = abi.decode(data, (uint256));
        }

        // The property: recorded LP recorded for this caller must be <= actual token balance OR be zero.
        // On P this holds because only curated pool callers can mint and that implies they actually are LP tokens; on M DEPLOYER could call and inflate recordedLP.
        assert(recordedLP == 0 || recordedLP <= actualLP);

        return (recordedLP, actualLP);
    }

    // Minimal payable/fallback to accept funds if needed by environment
    receive() external payable {}
    fallback() external payable {}
}

